CREATE TYPE public.app_role AS ENUM ('customer','employee','branch_manager','owner');
CREATE TABLE public.branches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), branch_name text NOT NULL, address text NOT NULL DEFAULT '', city text NOT NULL, phone text NOT NULL DEFAULT '', demand_threshold integer NOT NULL DEFAULT 3 CHECK (demand_threshold > 0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.branches TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.branches TO authenticated; GRANT ALL ON public.branches TO service_role; ALTER TABLE public.branches ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'customer', branch_id uuid REFERENCES public.branches(id), UNIQUE(user_id,role));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.branch_access(_branch uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND (role='owner' OR (role IN ('employee','branch_manager') AND branch_id=_branch))) $$;
CREATE FUNCTION public.branch_manager_access(_branch uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND (role='owner' OR (role='branch_manager' AND branch_id=_branch))) $$;
CREATE POLICY role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'owner'));
CREATE POLICY role_owner ON public.user_roles FOR ALL TO authenticated USING (public.has_role(auth.uid(),'owner')) WITH CHECK(public.has_role(auth.uid(),'owner'));
CREATE POLICY branches_public ON public.branches FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY branches_owner ON public.branches FOR ALL TO authenticated USING(public.has_role(auth.uid(),'owner')) WITH CHECK(public.has_role(auth.uid(),'owner'));
CREATE TABLE public.customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, phone text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', auth_user_id uuid UNIQUE, is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.customers TO authenticated; GRANT ALL ON public.customers TO service_role; ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, phone text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', branch_id uuid REFERENCES public.branches(id), auth_user_id uuid UNIQUE, is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.employees TO authenticated; GRANT ALL ON public.employees TO service_role; ALTER TABLE public.employees ENABLE ROW LEVEL SECURITY;
CREATE POLICY employees_read ON public.employees FOR SELECT TO authenticated USING(auth_user_id=auth.uid() OR public.branch_access(branch_id));
CREATE POLICY employees_owner ON public.employees FOR ALL TO authenticated USING(public.has_role(auth.uid(),'owner')) WITH CHECK(public.has_role(auth.uid(),'owner'));
CREATE TABLE public.cars (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), brand text NOT NULL, model text NOT NULL, variant text NOT NULL DEFAULT '', fuel_type text NOT NULL DEFAULT 'Petrol', transmission text NOT NULL DEFAULT 'Automatic', color text NOT NULL DEFAULT '', manufacturing_year integer NOT NULL DEFAULT 2026, price numeric(14,2) NOT NULL CHECK(price>=0), vin_chassis_no text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'Available' CHECK(status IN ('Available','Reserved','Sold','In Transit','Unassigned')), branch_id uuid REFERENCES public.branches(id), transfer_to uuid REFERENCES public.branches(id), image_key text NOT NULL DEFAULT 'sedan', is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.cars TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.cars TO authenticated; GRANT ALL ON public.cars TO service_role; ALTER TABLE public.cars ENABLE ROW LEVEL SECURITY;
CREATE POLICY cars_public ON public.cars FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY cars_manage ON public.cars FOR ALL TO authenticated USING(public.branch_manager_access(branch_id)) WITH CHECK(public.branch_manager_access(branch_id));
CREATE TABLE public.suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_name text NOT NULL, contact_person text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.suppliers TO authenticated; GRANT ALL ON public.suppliers TO service_role; ALTER TABLE public.suppliers ENABLE ROW LEVEL SECURITY;
CREATE POLICY suppliers_read ON public.suppliers FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('owner','branch_manager')));
CREATE POLICY suppliers_owner ON public.suppliers FOR ALL TO authenticated USING(public.has_role(auth.uid(),'owner')) WITH CHECK(public.has_role(auth.uid(),'owner'));
CREATE TABLE public.enquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.customers(id), employee_id uuid REFERENCES public.employees(id), car_id uuid REFERENCES public.cars(id), branch_id uuid NOT NULL REFERENCES public.branches(id), enquiry_type text NOT NULL DEFAULT 'Car Enquiry' CHECK(enquiry_type IN ('General Enquiry','Car Enquiry','Appointment','Test Drive','Unavailable Car Request','Booking Request')), enquiry_date timestamptz NOT NULL DEFAULT now(), appointment_date timestamptz, status text NOT NULL DEFAULT 'New', remarks text NOT NULL DEFAULT '', requested_brand text NOT NULL DEFAULT '', requested_model text NOT NULL DEFAULT '', requested_variant text NOT NULL DEFAULT '', procurement_decision text NOT NULL DEFAULT 'Pending', decision_by uuid REFERENCES public.employees(id), decision_at timestamptz, is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.enquiries TO authenticated; GRANT ALL ON public.enquiries TO service_role; ALTER TABLE public.enquiries ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.owns_customer(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.customers WHERE id=_id AND auth_user_id=auth.uid()) $$;
CREATE POLICY enquiries_read ON public.enquiries FOR SELECT TO authenticated USING(public.owns_customer(customer_id) OR public.branch_access(branch_id));
CREATE POLICY enquiries_create ON public.enquiries FOR INSERT TO authenticated WITH CHECK((public.owns_customer(customer_id) AND status IN ('New','Requested') AND employee_id IS NULL AND decision_by IS NULL AND decision_at IS NULL AND procurement_decision='Pending') OR public.branch_access(branch_id));
CREATE POLICY enquiries_staff ON public.enquiries FOR UPDATE TO authenticated USING(public.branch_access(branch_id)) WITH CHECK(public.branch_access(branch_id));
CREATE POLICY enquiries_delete ON public.enquiries FOR DELETE TO authenticated USING(public.branch_manager_access(branch_id));
CREATE POLICY customers_read ON public.customers FOR SELECT TO authenticated USING(auth_user_id=auth.uid() OR public.has_role(auth.uid(),'owner') OR EXISTS(SELECT 1 FROM public.enquiries WHERE customer_id=customers.id AND public.branch_access(branch_id)));
CREATE POLICY customers_self ON public.customers FOR UPDATE TO authenticated USING(auth_user_id=auth.uid()) WITH CHECK(auth_user_id=auth.uid());
CREATE POLICY customers_owner ON public.customers FOR ALL TO authenticated USING(public.has_role(auth.uid(),'owner')) WITH CHECK(public.has_role(auth.uid(),'owner'));
CREATE TABLE public.sales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.customers(id), car_id uuid NOT NULL REFERENCES public.cars(id), employee_id uuid NOT NULL REFERENCES public.employees(id), branch_id uuid NOT NULL REFERENCES public.branches(id), sale_date date NOT NULL DEFAULT current_date, sale_amount numeric(14,2) NOT NULL CHECK(sale_amount>0), sale_type text NOT NULL DEFAULT 'Enquiry-based', status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Confirmed','Completed','Cancelled')), payment_method text, amount_paid numeric(14,2) NOT NULL DEFAULT 0 CHECK(amount_paid>=0 AND amount_paid<=sale_amount), payment_status text GENERATED ALWAYS AS (CASE WHEN amount_paid=sale_amount THEN 'Completed' WHEN amount_paid>0 THEN 'Partial' ELSE 'Pending' END) STORED, is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.sales TO authenticated; GRANT ALL ON public.sales TO service_role; ALTER TABLE public.sales ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX one_active_sale_per_car ON public.sales(car_id) WHERE status<>'Cancelled';
CREATE POLICY sales_read ON public.sales FOR SELECT TO authenticated USING(public.owns_customer(customer_id) OR public.branch_access(branch_id));
CREATE POLICY sales_staff ON public.sales FOR ALL TO authenticated USING(public.branch_access(branch_id)) WITH CHECK(public.branch_access(branch_id));
CREATE TABLE public.services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), car_id uuid NOT NULL REFERENCES public.cars(id), customer_id uuid NOT NULL REFERENCES public.customers(id), employee_id uuid NOT NULL REFERENCES public.employees(id), branch_id uuid NOT NULL REFERENCES public.branches(id), service_date date NOT NULL DEFAULT current_date, service_type text NOT NULL, description text NOT NULL DEFAULT '', cost numeric(14,2) NOT NULL DEFAULT 0 CHECK(cost>=0), status text NOT NULL DEFAULT 'Scheduled' CHECK(status IN ('Scheduled','In Progress','Completed','Cancelled')), is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.services TO authenticated; GRANT ALL ON public.services TO service_role; ALTER TABLE public.services ENABLE ROW LEVEL SECURITY;
CREATE POLICY services_read ON public.services FOR SELECT TO authenticated USING(public.owns_customer(customer_id) OR public.branch_access(branch_id));
CREATE POLICY services_staff ON public.services FOR ALL TO authenticated USING(public.branch_access(branch_id)) WITH CHECK(public.branch_access(branch_id));
CREATE TABLE public.purchases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid NOT NULL REFERENCES public.suppliers(id), car_id uuid NOT NULL REFERENCES public.cars(id), employee_id uuid NOT NULL REFERENCES public.employees(id), branch_id uuid NOT NULL REFERENCES public.branches(id), purchase_date date NOT NULL DEFAULT current_date, purchase_cost numeric(14,2) NOT NULL CHECK(purchase_cost>=0), status text NOT NULL DEFAULT 'Pending Approval' CHECK(status IN ('Pending Approval','Approved','Ordered','Received','Cancelled')), is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.purchases TO authenticated; GRANT ALL ON public.purchases TO service_role; ALTER TABLE public.purchases ENABLE ROW LEVEL SECURITY;
CREATE POLICY purchases_read ON public.purchases FOR SELECT TO authenticated USING(public.branch_access(branch_id));
CREATE POLICY purchases_manage ON public.purchases FOR ALL TO authenticated USING(public.branch_manager_access(branch_id)) WITH CHECK(public.branch_manager_access(branch_id));
CREATE FUNCTION public.on_cdms_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.customers(name,email,auth_user_id) VALUES(COALESCE(NULLIF(NEW.raw_user_meta_data->>'name',''),split_part(NEW.email,'@',1)),COALESCE(NEW.email,''),NEW.id); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'customer'); RETURN NEW; END $$;
CREATE TRIGGER cdms_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.on_cdms_signup();
CREATE FUNCTION public.validate_sale() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.cars; e public.employees; BEGIN SELECT * INTO v FROM public.cars WHERE id=NEW.car_id FOR UPDATE; SELECT * INTO e FROM public.employees WHERE id=NEW.employee_id; IF v.branch_id IS DISTINCT FROM NEW.branch_id OR e.branch_id IS DISTINCT FROM NEW.branch_id THEN RAISE EXCEPTION 'Car and employee must belong to the sale branch'; END IF; IF TG_OP='INSERT' AND NEW.status<>'Cancelled' AND v.status<>'Available' THEN RAISE EXCEPTION 'Car is not available'; END IF; IF TG_OP='UPDATE' AND (NEW.car_id<>OLD.car_id OR NEW.branch_id<>OLD.branch_id OR NEW.customer_id<>OLD.customer_id) THEN RAISE EXCEPTION 'Sale identity cannot be changed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER sale_validate BEFORE INSERT OR UPDATE ON public.sales FOR EACH ROW EXECUTE FUNCTION public.validate_sale();
CREATE FUNCTION public.sync_sale_car() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.cars SET status=CASE NEW.status WHEN 'Completed' THEN 'Sold' WHEN 'Cancelled' THEN 'Available' ELSE 'Reserved' END,updated_at=now() WHERE id=NEW.car_id; RETURN NEW; END $$;
CREATE TRIGGER sale_inventory AFTER INSERT OR UPDATE ON public.sales FOR EACH ROW EXECUTE FUNCTION public.sync_sale_car();
CREATE FUNCTION public.validate_service() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.employees WHERE id=NEW.employee_id AND branch_id=NEW.branch_id) OR NOT EXISTS(SELECT 1 FROM public.sales WHERE car_id=NEW.car_id AND customer_id=NEW.customer_id AND status='Completed') THEN RAISE EXCEPTION 'Service must reference the correct owner and branch employee'; END IF; RETURN NEW; END $$;
CREATE TRIGGER service_validate BEFORE INSERT OR UPDATE ON public.services FOR EACH ROW EXECUTE FUNCTION public.validate_service();
CREATE FUNCTION public.sync_purchase_car() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='Received' THEN UPDATE public.cars SET status='Available',branch_id=NEW.branch_id,updated_at=now() WHERE id=NEW.car_id AND status IN ('Unassigned','In Transit'); IF NOT FOUND THEN RAISE EXCEPTION 'Receipt requires an unassigned or in-transit car'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER purchase_receipt AFTER INSERT OR UPDATE ON public.purchases FOR EACH ROW WHEN (NEW.status='Received') EXECUTE FUNCTION public.sync_purchase_car();
CREATE INDEX enquiries_demand ON public.enquiries(enquiry_type,branch_id,requested_brand,requested_model,requested_variant,enquiry_date);
CREATE INDEX enquiries_customer ON public.enquiries(customer_id); CREATE INDEX cars_branch_status ON public.cars(branch_id,status);
